<section class="dashboard-head"><div class="container"><div class="eyebrow">VENDOR WORKSPACE</div><h1>Let's make good <em>work.</em></h1><p>Manage your catalogue and keep customer orders moving.</p></div></section><section class="section-pad"><div class="container"><div class="dashboard-cards"><div class="metric-card"><small>ACTIVE SERVICES</small><strong><?= $serviceCount ?></strong><span>In your catalogue</span></div><div class="metric-card"><small>ORDERS</small><strong><?= count($orders) ?></strong><span>Recent orders shown</span></div><div class="metric-card"><small>FULFILMENT</small><strong>↗</strong><span>Keep statuses up to date</span></div></div><div class="row g-4 mt-2"><div class="col-lg-5"><div class="checkout-card"><h2>Add a service</h2><form method="post" action="<?= e(url('vendor/services/save')) ?>" class="form-stack"><?= csrf_field() ?><label>Service name<input class="form-control" name="name" required maxlength="150"></label><label>Description<textarea class="form-control" name="description" rows="2"></textarea></label><label>Category<select class="form-select" name="category_id"><option value="">Choose category</option><?php foreach(db()->query('SELECT id,name FROM categories WHERE status="active"') as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Service type<select class="form-select" name="service_type"><option value="printing">Printing</option><option value="packaging">Packaging</option></select></label><label>Starting price (PKR per unit)<input class="form-control" type="number" min="1" step="0.01" name="base_price" required></label><label>Material<input class="form-control" name="material" placeholder="e.g. 350gsm matte card"></label><label>Size / dimensions<input class="form-control" name="size_label" placeholder="e.g. A4, 210 × 297 mm"></label><button class="btn btn-green">Save service ↗</button></form></div></div><div class="col-lg-7"><div class="dashboard-section-title"><h2>Recent orders</h2></div><div class="orders-table-wrap"><table class="table align-middle"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status / update</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?= (int)$o['id'] ?><small class="d-block muted-text"><?= e(date('d M',strtotime($o['created_at']))) ?></small></td><td><?= e($o['customer_name']) ?></td><td><?= money($o['total_amount']) ?></td><td><form method="post" action="<?= e(url('orders/status')) ?>" class="status-form"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><select class="form-select form-select-sm" name="status"><?php foreach(['accepted','processing','dispatched','delivered','cancelled'] as $st): ?><option value="<?= $st ?>" <?= $o['status']===$st?'selected':'' ?>><?= ucfirst($st) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-dark mt-1">Update</button></form></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="4" class="text-center py-4">New orders will appear here.</td></tr><?php endif; ?></tbody></table></div></div></div></div></section>
